<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useEvaluationStore } from '@/stores/evaluation'
import { useUserStore } from '@/stores/user'
import { useMarketStore } from '@/stores/market'
import placeholderPhoto from '@/assets/teachers/placeholder.jpg'
import {
  Star,
    MessageSquareText,
      QrCode,
        CheckCircle2,
          Sparkles,
            Lock,
              Info,
                Clock,
                  MapPin,
                    Flame,
                      UserRound,
                        UploadCloud,
                          Search
                          } from 'lucide-vue-next'
                          import { ElMessage } from 'element-plus'
                          
                          const evaluationStore = useEvaluationStore()
                          const userStore = useUserStore()
                          const marketStore = useMarketStore()
                          const route = useRoute()
                          const router = useRouter()
                          
                          const selectedCode = ref<string>(
                            typeof route.query.teacher === 'string' ? route.query.teacher : marketStore.stocks[0]?.code || ''
                            )
                            const expandedCode = ref<string>('')
                            const importDialogVisible = ref(false)
                            const rating = ref<number>(5)
                            const hoverRating = ref<number>(0)
                            const selectedTags = ref<string[]>([])
                            const comment = ref<string>('')
                            const isAnonymous = ref<boolean>(true)
                            const searchQuery = ref('')
                            const currentPage = ref(1)
                            const pageSize = 15
                            
                            const rankedStocks = computed(() =>
                              [...marketStore.stocks].sort(
                                  (a, b) => b.rating - a.rating || b.ratingCount - a.ratingCount || a.name.localeCompare(b.name)
                                    )
                                    )
                                    
                                    const filteredStocks = computed(() => {
                                      const keyword = searchQuery.value.trim().toLowerCase()
                                        if (!keyword) return rankedStocks.value
                                        
                                          return rankedStocks.value.filter((stock) =>
                                              [stock.name, stock.teacherName, stock.course, stock.department, stock.code]
                                                    .some((field) => field.toLowerCase().includes(keyword))
                                                      )
                                                      })
                                                      
                                                      const visibleStocks = computed(() => {
                                                        const start = (currentPage.value - 1) * pageSize
                                                          return filteredStocks.value.slice(start, start + pageSize)
                                                          })
                                                          
                                                          watch(searchQuery, () => {
                                                            currentPage.value = 1
                                                            })
                                                            
                                                            const presetTags = [
                                                              '深入浅出',
                                                                '干货满满',
                                                                  '互动热烈',
                                                                    '节奏适中',
                                                                      '案例鲜活',
                                                                        '实验丰富',
                                                                          '前沿视野',
                                                                            '作业量大',
                                                                              '点名严格',
                                                                                '给分友好'
                                                                                ]
                                                                                
                                                                                const selectedStock = computed(() => {
                                                                                  return marketStore.stocks.find((s) => s.code === selectedCode.value) || marketStore.stocks[0]
                                                                                  })
                                                                                  
                                                                                  const mySession = computed(() => {
                                                                                    return evaluationStore.courses.find((c) => c.stockCode === selectedCode.value)
                                                                                    })
                                                                                    
                                                                                    const teacherReviews = computed(() => {
                                                                                      return evaluationStore.evaluations.filter(
                                                                                          (e) => e.stockCode === selectedCode.value && e.status === 'APPROVED'
                                                                                            )
                                                                                            })
                                                                                            
                                                                                            const reviewCount = computed(() => {
                                                                                              return evaluationStore.evaluations.filter((e) => e.stockCode === selectedCode.value).length
                                                                                              })
                                                                                              
                                                                                              function selectTeacher(code: string) {
                                                                                                selectedCode.value = code
                                                                                                  expandedCode.value = expandedCode.value === code ? '' : code
                                                                                                  }
                                                                                                  
                                                                                                  function goToCourses() {
                                                                                                    router.push('/courses')
                                                                                                    }
                                                                                                    
                                                                                                    function onPhotoError(e: Event) {
                                                                                                      ;(e.target as HTMLImageElement).src = placeholderPhoto
                                                                                                      }
                                                                                                      
                                                                                                      function toggleTag(tag: string) {
                                                                                                        if (selectedTags.value.includes(tag)) {
                                                                                                            selectedTags.value = selectedTags.value.filter((t) => t !== tag)
                                                                                                              } else {
                                                                                                                  selectedTags.value.push(tag)
                                                                                                                    }
                                                                                                                    }
                                                                                                                    
                                                                                                                    function handleSignIn(sessionId: string) {
                                                                                                                      const res = evaluationStore.signInCourse(sessionId)
                                                                                                                        if (res.success) {
                                                                                                                            ElMessage.success(res.message)
                                                                                                                              } else {
                                                                                                                                  ElMessage.warning(res.message)
                                                                                                                                    }
                                                                                                                                    }
                                                                                                                                    
                                                                                                                                    function openEvaluate(sessionId: string) {
                                                                                                                                      const session = evaluationStore.courses.find((c) => c.id === sessionId)
                                                                                                                                        if (session) {
                                                                                                                                            selectedCode.value = session.stockCode
                                                                                                                                              }
                                                                                                                                              }
                                                                                                                                              
                                                                                                                                              function handleSubmitEvaluation() {
                                                                                                                                                if (userStore.user.role === 'EXTERNAL') {
                                                                                                                                                    ElMessage.warning('校外用户不可参与校内课堂评教，仅校内认证学生可提交')
                                                                                                                                                        return
                                                                                                                                                          }
                                                                                                                                                            if (!mySession.value) return
                                                                                                                                                              if (!mySession.value.isSigned) {
                                                                                                                                                                  ElMessage.error('请先完成本节课签到打卡，再提交评分')
                                                                                                                                                                      return
                                                                                                                                                                        }
                                                                                                                                                                          if (!comment.value.trim()) {
                                                                                                                                                                              ElMessage.warning('请填写一句锐评内容')
                                                                                                                                                                                  return
                                                                                                                                                                                    }
                                                                                                                                                                                    
                                                                                                                                                                                      const res = evaluationStore.submitEvaluation({
                                                                                                                                                                                          sessionId: mySession.value.id,
                                                                                                                                                                                              rating: rating.value,
                                                                                                                                                                                                  tags: selectedTags.value,
                                                                                                                                                                                                      comment: comment.value,
                                                                                                                                                                                                          anonymous: isAnonymous.value
                                                                                                                                                                                                            })
                                                                                                                                                                                                            
                                                                                                                                                                                                              if (res.success) {
                                                                                                                                                                                                                  ElMessage.success(res.message)
                                                                                                                                                                                                                      comment.value = ''
                                                                                                                                                                                                                          selectedTags.value = []
                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                ElMessage.error(res.message)
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  </script>
                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                  <template>
                                                                                                                                                                                                                                    <div class="evaluation-view">
                                                                                                                                                                                                                                        <!-- Top Row: Banner + My Courses -->
                                                                                                                                                                                                                                            <div v-if="false" class="eval-top-row">
                                                                                                                                                                                                                                                  <div class="eval-hero">
                                                                                                                                                                                                                                                          <div class="badge-pill">
                                                                                                                                                                                                                                                                    <Flame :size="15" />
                                                                                                                                                                                                                                                                              <span>杭电教师评分墙 · 虎扑式</span>
                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                              <h2 class="hero-title">给老师打分，写一句锐评</h2>
                                                                                                                                                                                                                                                                                                      <p class="hero-desc">
                                                                                                                                                                                                                                                                                                                全站可查看教师星级与锐评；选修该课程的同学签到后即可打分、发锐评，评分聚合影响次日基本面因子。
                                                                                                                                                                                                                                                                                                                        </p>
                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                    <!-- Top-Right: My Courses -->
                                                                                                                                                                                                                                                                                                                                          <div class="my-courses-card">
                                                                                                                                                                                                                                                                                                                                                  <div class="panel-title">
                                                                                                                                                                                                                                                                                                                                                            <UserRound :size="16" class="text-blue" />
                                                                                                                                                                                                                                                                                                                                                                      <span>我的课程</span>
                                                                                                                                                                                                                                                                                                                                                                                <span class="sub-count">{{ evaluationStore.courses.length }} 门</span>
                                                                                                                                                                                                                                                                                                                                                                                          <button class="import-btn" @click="importDialogVisible = true">
                                                                                                                                                                                                                                                                                                                                                                                                      <UploadCloud :size="14" /> 导入课表
                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                <div class="my-course-list">
                                                                                                                                                                                                                                                                                                                                                                                                                                          <div v-for="session in evaluationStore.courses" :key="session.id" class="my-course-item">
                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="mc-main">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span class="mc-course">{{ session.courseName }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span class="mc-meta">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span>{{ session.teacherName }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span class="mc-dot">·</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span><Clock :size="12" /> {{ session.time }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span class="mc-dot">·</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span><MapPin :size="12" /> {{ session.room }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="mc-actions">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v-if="!session.isSigned"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      class="mini-btn signin"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      @click="handleSignIn(session.id)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <QrCode :size="13" /> 签到
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v-else-if="!session.isEvaluated"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                class="mini-btn evaluate"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                @click="openEvaluate(session.id)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              去评价
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span v-else class="mini-done"><CheckCircle2 :size="13" /> 已评</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="evaluation-workspace">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <!-- 评分榜与查询 -->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <section class="rating-board panel">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="board-head">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="board-kicker"><Flame :size="14" /> 全场评分</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h3>教师评分榜</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p>按综合星级排序，选择教师后可查看课程信息与同学锐评。</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="board-actions">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <el-button type="primary" @click="goToCourses">进入我的课程</el-button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <el-input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v-model="searchQuery"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          class="teacher-search"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      clearable
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  :prefix-icon="Search"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              placeholder="查教师、课程、院系或工号"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="board-status">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span v-if="searchQuery">查询到 {{ filteredStocks.length }} 位教师</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span v-else>共 {{ marketStore.stocks.length }} 位教师，按综合星级排序</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span class="board-hint">每页 {{ pageSize }} 位，{{ searchQuery ? '点击结果即可切换评分与锐评' : '输入关键词查询全部教师' }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div v-if="visibleStocks.length" class="teacher-grid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v-for="(stock, index) in visibleStocks"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    :key="stock.code"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                class="teacher-row"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="teacher-card" :class="{ active: stock.code === selectedCode }" @click="selectTeacher(stock.code)">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span class="rank-number">{{ (currentPage - 1) * pageSize + index + 1 }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="avatar-wrap">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <img :src="stock.photo" :alt="stock.name" @error="onPhotoError" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="teacher-summary">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="t-name-row">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span class="t-name">{{ stock.name }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span class="t-code">{{ stock.code }}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="t-dept">{{ stock.department }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="t-course">{{ stock.course }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="t-rating">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Star :size="15" class="star-icon" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <strong>{{ stock.rating.toFixed(1) }}</strong>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <small>{{ stock.ratingCount }} 人评</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div v-if="expandedCode === stock.code" class="teacher-drawer">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="drawer-grid">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="drawer-profile">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <img class="profile-photo" :src="stock.photo" :alt="stock.name" @error="onPhotoError" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="profile-info">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="profile-name-row"><span class="code-pill">{{ stock.code }}</span><h3 class="profile-name">{{ stock.name }}</h3></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="profile-sub">{{ stock.teacherName }} · {{ stock.department }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="profile-course">主讲课程：{{ stock.course || '暂未录入' }}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div class="profile-stars"><Star :size="15" class="star-icon" /><strong>{{ stock.rating.toFixed(1) }}</strong><span class="gold">综合星级</span><span class="divider">|</span><span>{{ stock.ratingCount }} 人评</span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p class="profile-desc">{{ stock.description }}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
