                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div v-else class="score-form">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div class="form-group"><label class="form-label"><span>课程星级打分 (1~5星)</span><span class="rating-hint">{{ rating }} 星</span></label><div class="star-picker"><button v-for="s in 5" :key="s" class="star-pick-btn" :class="{ active: (hoverRating || rating) >= s }" @mouseenter="hoverRating = s" @mouseleave="hoverRating = 0" @click="rating = s">★</button></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div class="tag-selector"><button v-for="tag in presetTags" :key="tag" class="tag-btn" :class="{ selected: selectedTags.includes(tag) }" @click="toggleTag(tag)">{{ tag }}</button></div>
