div class="rev-user"><span class="rev-name">{{ rev.studentName }}</span><span class="rev-time">{{ rev.createTime }}</span></div><span class="rev-stars">★ {{ rev.rating }} 星</span></div><div class="rev-tags"><span v-for="tag in rev.tags" :key="tag" class="tag-chip">{{ tag }}</span></div><p class="rev-text">{{ rev.comment }}</p></div>
